-- Phase 61: reproducibility companion for Phase 60.
-- Exact installed RPC behavior is intentionally re-declared here; ownership is checked server-side.
create or replace function public.parceria_request(_org_origem uuid,_org_parceira uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid(); i uuid; begin if u is null then return jsonb_build_object('ok',false,'reason','unauthenticated'); end if; if not public.usuario_dono_org(_org_origem,u) and not public.eh_super_admin(u) then return jsonb_build_object('ok',false,'reason','forbidden'); end if; if _org_origem=_org_parceira or not exists(select 1 from public.organizations where id=_org_parceira and coalesce(ativo,true)=true) then return jsonb_build_object('ok',false,'reason','invalid_partner'); end if; insert into public.parcerias(org_origem,org_parceira,status) values(_org_origem,_org_parceira,'pending') on conflict(org_origem,org_parceira) do update set status=case when public.parcerias.status='declined' then 'pending' else public.parcerias.status end,updated_at=now() returning id into i; return jsonb_build_object('ok',true,'id',i); end$$;
create or replace function public.parceria_respond(_parceria_id uuid,_accept boolean) returns jsonb language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid(); r public.parcerias%rowtype; begin if u is null then return jsonb_build_object('ok',false,'reason','unauthenticated'); end if; select * into r from public.parcerias where id=_parceria_id for update; if not found then return jsonb_build_object('ok',false,'reason','not_found'); end if; if not public.usuario_dono_org(r.org_parceira,u) and not public.eh_super_admin(u) then return jsonb_build_object('ok',false,'reason','forbidden'); end if; if r.status<>'pending' then return jsonb_build_object('ok',false,'reason','invalid_status'); end if; update public.parcerias set status=case when _accept then 'active' else 'declined' end,updated_at=now() where id=_parceria_id; return jsonb_build_object('ok',true); end$$;
create or replace function public.parceria_set_rules(_parceria_id uuid,_min_order numeric,_discount numeric) returns jsonb language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid(); r public.parcerias%rowtype; begin if u is null then return jsonb_build_object('ok',false,'reason','unauthenticated'); end if; select * into r from public.parcerias where id=_parceria_id for update; if not found then return jsonb_build_object('ok',false,'reason','not_found'); end if; if not (public.usuario_dono_org(r.org_origem,u) or public.usuario_dono_org(r.org_parceira,u) or public.eh_super_admin(u)) then return jsonb_build_object('ok',false,'reason','forbidden'); end if; update public.parcerias set min_order_value=greatest(coalesce(_min_order,0),0),discount_percent=least(greatest(coalesce(_discount,0),0),100),updated_at=now() where id=_parceria_id; return jsonb_build_object('ok',true); end$$;
create or replace function public.parceria_toggle(_parceria_id uuid,_enabled boolean) returns jsonb language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid(); r public.parcerias%rowtype; begin if u is null then return jsonb_build_object('ok',false,'reason','unauthenticated'); end if; select * into r from public.parcerias where id=_parceria_id for update; if not found then return jsonb_build_object('ok',false,'reason','not_found'); end if; if public.usuario_dono_org(r.org_origem,u) then update public.parcerias set habilitada_origem=_enabled,updated_at=now() where id=_parceria_id; elsif public.usuario_dono_org(r.org_parceira,u) then update public.parcerias set habilitada_parceira=_enabled,updated_at=now() where id=_parceria_id; elsif public.eh_super_admin(u) then update public.parcerias set habilitada_origem=_enabled,habilitada_parceira=_enabled,updated_at=now() where id=_parceria_id; else return jsonb_build_object('ok',false,'reason','forbidden'); end if; return jsonb_build_object('ok',true); end$$;
revoke all on function public.parceria_request(uuid,uuid),public.parceria_respond(uuid,boolean),public.parceria_set_rules(uuid,numeric,numeric),public.parceria_toggle(uuid,boolean) from public,anon;
grant execute on function public.parceria_request(uuid,uuid),public.parceria_respond(uuid,boolean),public.parceria_set_rules(uuid,numeric,numeric),public.parceria_toggle(uuid,boolean) to authenticated;
